package hooks

import (
	"encoding/json"
	"fmt"
	"strings"

	corehooks "github.com/sloprail/harness-mocks/internal/hooks"
)

// Decision is what one hook command decided about the action it was asked
// about.
type Decision struct {
	// Permission is "deny", "ask" or "allow", or "" when the hook decided
	// nothing.
	Permission string
	// Blocked: the hook blocked by its exit status, not by its output.
	Blocked bool
	// Message is what a refusal says: the hook's stderr after "Hook blocked
	// with message:", the user_message of a deny, or the invalid-JSON notice.
	Message string
	// Context is the additional_context the hook gave, for an event that takes
	// it (sessionStart, postToolUse, postToolUseFailure).
	Context string
}

// failClosedNote opens what a fail-closed hook's failure says.
const failClosedNote = "Tool blocked because this hook is configured to fail closed (block when it fails). "

// Interpret reads one hook command's outcome for the event. Its exit status
// classifies it (the core's VerdictOf): 2 blocks, which is a deny; any other
// non-zero status fails open, and the hook's output is not read. A hook
// configured failClosed blocks on any failure instead: a non-zero status, or
// no output from a permission hook. On a permission event, output that is not
// a JSON object blocks the action for safety (a hook that prints nothing
// allows it); otherwise its permission and user_message are read.
//
// sr:provides hook-exit-code-semantics/cursor
// sr:docs https://cursor.com/docs/hooks#command-based-hooks
func Interpret(e Event, h Entry, o corehooks.Outcome) Decision {
	if !o.Counts() {
		// The core says a result is not read when the hook timed out (it and its
		// children were killed, and whatever it printed is discarded) or could not
		// start: the action goes on. Cursor's one difference: a hook that timed
		// out and fails closed blocks, saying it timed out after the limit it ran
		// under.
		// sr:provides hook-timeout/cursor
		// sr:docs https://cursor.com/docs/hooks#per-script-configuration-options
		if corehooks.FailsClosed(o, h.FailClosed) {
			return Decision{Permission: "deny", Blocked: true, Message: fmt.Sprintf("%sHook %q execution failed: Hook script timed out after %dms", failClosedNote, h.Command, o.Timeout.Milliseconds())}
		}
		return Decision{}
	}
	verdict := corehooks.NonBlockingError
	if o.Exit >= 0 {
		verdict = corehooks.VerdictOf(o.Exit, h.FailClosed)
	}
	switch verdict {
	case corehooks.Blocked:
		if o.Exit != 2 {
			return Decision{Permission: "deny", Blocked: true, Message: fmt.Sprintf("%sHook %q failed with exit code %d: %s", failClosedNote, h.Command, o.Exit, strings.TrimSpace(o.Stderr))}
		}
		return Decision{Permission: "deny", Blocked: true, Message: "Hook blocked with message: " + strings.TrimSpace(o.Stderr)}
	case corehooks.NonBlockingError:
		return Decision{}
	}
	out := strings.TrimSpace(o.Stdout)
	if e.addsContext() {
		// sr:provides hook-additional-context/cursor
		// sr:docs https://cursor.com/docs/hooks#posttooluse
		var p struct {
			Context string `json:"additional_context"`
		}
		if corehooks.IsJSONOutput(out, isOutputField) && json.Unmarshal([]byte(out), &p) == nil {
			return Decision{Context: p.Context}
		}
		return Decision{}
	}
	if !e.permission() {
		return Decision{}
	}
	if out == "" {
		if corehooks.SilentFails(out, h.FailClosed) {
			return Decision{Permission: "deny", Message: fmt.Sprintf("%sHook %q returned no output.", failClosedNote, h.Command)}
		}
		return Decision{}
	}
	var p struct {
		Permission  string `json:"permission"`
		UserMessage string `json:"user_message"`
	}
	// What counts as JSON output is the core's; the fields read from it are Cursor's.
	if !corehooks.IsJSONOutput(out, isOutputField) || json.Unmarshal([]byte(out), &p) != nil || !validPermission(p.Permission) {
		return Decision{Permission: "deny", Message: fmt.Sprintf("Hook %q returned invalid JSON. The command was blocked for safety.", h.Command)}
	}
	return Decision{Permission: p.Permission, Message: p.UserMessage}
}

func validPermission(p string) bool { return p == "" || p == "allow" || p == "deny" || p == "ask" }

// isOutputField reports whether a key is one a Cursor hook's output sets.
func isOutputField(key string) bool {
	switch key {
	case "permission", "user_message", "agent_message", "continue", "env", "additional_context":
		return true
	}
	return false
}

// Refusal is whether several hooks' decisions refuse the call, and what the
// refusal says: the core decides (a deny from any hook refuses, whatever the
// others decided, and a block by exit status outranks a deny in output); the
// messages of the hooks that refused are concatenated. An "ask" decides
// nothing: the mock models a run that no one is there to ask.
//
// sr:provides pretooluse-refusal/cursor
// sr:docs https://cursor.com/docs/hooks#configuration
func Refusal(ds []Decision) (refused bool, message string) {
	var vote corehooks.PreToolVote
	var blockMsgs, denyMsgs []string
	for _, d := range ds {
		switch {
		case d.Blocked:
			vote.Blocked = true
			blockMsgs = append(blockMsgs, d.Message)
		case d.Permission == "deny":
			vote.Denied = true
			denyMsgs = append(denyMsgs, d.Message)
		}
	}
	vote.BlockReason, vote.DenyReason = strings.Join(blockMsgs, "\n"), strings.Join(denyMsgs, "\n")
	return corehooks.PreToolRefusal([]corehooks.PreToolVote{vote})
}
package runner

import (
	"context"
	"fmt"
	"strings"
	"time"

	"github.com/sloprail/harness-mocks/cursor-mock/internal/childenv"
	"github.com/sloprail/harness-mocks/cursor-mock/internal/hooks"
	"github.com/sloprail/harness-mocks/internal/procexec"
	coresession "github.com/sloprail/harness-mocks/internal/session"
	"github.com/sloprail/harness-mocks/internal/turnloop"
)

// session is one run's state, and the harness side (turnloop.Host) of its turn.
type session struct {
	cfg     Config
	id      string
	tr      *transcript
	hooks   *hooks.Hooks
	started time.Time
	texts   []string // what the agent said, in order: the result frame's text
	// named: hook payloads carry the transcript path. Cursor leaves it null
	// until the conversation's first tool call is past its preToolUse hooks
	// (recorded: runs/tool-failure), though the file is there from the first
	// record.
	named bool
	// added is the context the hooks have handed the agent so far (their
	// additional_context), in the order their events fired and, within an event,
	// the order the hooks are configured in.
	added []string
}

// keep adds the context the hooks of one event gave to the agent's: all of it,
// when several hooks gave some.
//
// sr:provides hook-additional-context/cursor
func (s *session) keep(ds []hooks.Decision) {
	for _, d := range ds {
		if d.Context != "" {
			s.added = append(s.added, d.Context)
		}
	}
}

// Context is what the agent has been handed by hooks, all of it (turnloop.Params.Added).
func (s *session) Context() string { return strings.Join(s.added, "\n") }

// Run plays one run: the stream's opening frames, the sessionStart hooks, the
// script's turns until its result, the sessionEnd hooks, and then the result
// frame, last on the stream. A single prompt runs to completion without
// interaction, streaming one record per line and ending with one result. The
// sessionEnd hook says the session completed: a non-interactive run has no
// other reason to report.
//
// The sessionStart hook fires once, before the first turn, and what it prints or
// exits with does not stop the session (recorded: runs/session-start-block); the
// payload says no source, as Cursor's does not.
//
// sr:provides noninteractive-run/cursor
// sr:provides session-end-hook/cursor
// sr:provides session-start-hook/cursor
// sr:docs https://cursor.com/docs/hooks#sessionend
// sr:docs https://cursor.com/docs/hooks#sessionstart
func Run(ctx context.Context, cfg Config) error {
	s := &session{cfg: cfg, id: coresession.NewID(), started: time.Now()}
	var err error
	if s.tr, err = newTranscript(cfg.Home, cfg.Dir, s.id); err != nil {
		return fmt.Errorf("cursor-mock: %w", err)
	}
	conf, err := hooks.Load(cfg.Dir)
	if err != nil {
		return fmt.Errorf("cursor-mock: %w", err)
	}
	s.hooks = &hooks.Hooks{Config: conf, Dir: cfg.Dir, Env: s.hookEnv, Common: s.common}
	s.forward(initFrame(s.id, cfg.Dir))
	s.forward(userFrame(s.id, cfg.Prompt))
	s.keep(s.hooks.Fire(ctx, hooks.SessionStart, hooks.NoSubject, map[string]any{"is_background_agent": false}))
	s.tr.user(cfg.Prompt) // the transcript file does not exist yet when the start hook runs
	_, runErr := turnloop.Run(ctx, s, turnloop.Params{Script: cfg.Script, Dir: cfg.Dir, Environ: cfg.Environ, Prompt: cfg.Prompt, Added: s.Context})
	s.named = true
	s.hooks.Fire(ctx, hooks.SessionEnd, hooks.NoSubject, map[string]any{
		"reason": "completed", "duration_ms": time.Since(s.started).Milliseconds(),
		"is_background_agent": false, "final_status": "completed",
	})
	s.tr.end()
	if runErr != nil {
		return fmt.Errorf("cursor-mock: %w", runErr)
	}
	s.forward(resultFrame(s.id, strings.Join(s.texts, ""), time.Since(s.started)))
	return nil
}

// hookEnv is the environment of a hook command: the harness's own, with the
// facts Cursor gives a hook (recorded: runs/subprocess-session-env,
// runs/nested-session-env).
func (s *session) hookEnv() []string {
	return procexec.Env(s.cfg.Environ,
		childenv.HookIdentity(s.cfg.Dir, s.common().TranscriptPath), childenv.HookDefaults(s.cfg.Dir, s.cfg.Version))
}

// common is what every hook payload carries now: the transcript path only once
// the conversation has a transcript.
func (s *session) common() hooks.Common {
	c := hooks.Common{SessionID: s.id, Dir: s.cfg.Dir, Version: s.cfg.Version}
	if s.named && s.tr.exists() {
		c.TranscriptPath = s.tr.path
	}
	return c
}

// forward prints one stream-json line.
func (s *session) forward(line []byte) { fmt.Fprintf(s.cfg.Stdout, "%s\n", line) }
